package com.smartexam.service;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl; import com.smartexam.entity.Submissions; import com.smartexam.mapper.SubmissionsMapper; import org.springframework.stereotype.Service;
@Service public class SubmissionsService extends ServiceImpl<SubmissionsMapper, Submissions> { public Submissions lockById(Long id){return baseMapper.selectByIdForUpdate(id);} public java.util.List<Submissions> lockByExamId(Long examId){return baseMapper.selectByExamIdForUpdate(examId);} public Submissions findByExamAndStudent(Long examId, Long studentId) { return baseMapper.selectByExamAndStudent(examId, studentId); } public java.util.List<Submissions> findByExamId(Long examId){return baseMapper.selectByExamId(examId);} public java.util.List<Submissions> findPublishedByStudent(Long studentId){return baseMapper.selectPublishedByStudent(studentId);} }
